window.NULLIFY_SEARCH_DATA = [{"id":"NL-I1","kind":"issue","title":"Poor `var` Support","status":"Resolved(`0.0.1`)","url":"issues/NL-I1.html","statusLabel":"Resolved: on version 0.0.1","content":"Local variables declared with var were not recognized as fold targets. Annotated var declarations behaved exactly like unannotated ones, instead of inferring the type, parsing its annotations, and folding the type accordingly. Annotated var local variables now infer their type and fold accordingly; unannotated ones are left untouched."},{"id":"NL-I2","kind":"issue","title":"Custom Annotation Registry Support in Folding Configuration","status":"Resolved(`0.0.1`)","url":"issues/NL-I2.html","statusLabel":"Resolved: on version 0.0.1","content":"There was no way to register custom nullability annotations, so user-defined or non-standard annotations were never recognized by the folding engine. Users can now register custom @Nullable/@NotNull annotations and have them recognized by the folding engine."},{"id":"NL-I3","kind":"issue","title":"Pipeline Logging and Observability","status":"Resolved","url":"issues/NL-I3.html","statusLabel":"Resolved: on version ","content":"The core processing pipeline had no structured logging across its stages, making it difficult to debug issues or trace execution flow during folding. Structured trace, debug, and warning logging now covers all pipeline stages, making issues easier to diagnose."},{"id":"NL-I4","kind":"issue","title":"Preservation of Non-Nullability Annotations in Fold Placeholders","status":"Resolved(`0.0.1`)","url":"issues/NL-I4.html","statusLabel":"Resolved: on version 0.0.1","content":"Non-nullability annotations (such as @Value(\"...\")) were stripped or lost from fold placeholders. In addition, types annotated with only a non-nullability annotation — no @Nullable/@NotNull — were incorrectly folded. Non-nullability annotations are preserved in fold placeholders, and types carrying only non-nullability annotations no longer fold."},{"id":"NL-I5","kind":"issue","title":"Introduce `IrNode.Ignored` for Primitives and Unannotated `var`","status":"Resolved","url":"issues/NL-I5.html","statusLabel":"Resolved: on version ","content":"The \"unknown\" marker was over-used for simple non-foldable constructs like primitive types and unannotated var declarations, which obscured genuine parsing errors. Simple non-foldable constructs now use a dedicated \"ignored\" marker, so genuine parsing failures remain easy to spot."},{"id":"NL-I6","kind":"issue","title":"Array and Vararg Folding Redesign via Type Normalization","status":"Resolved(`0.0.1`)","url":"issues/NL-I6.html","statusLabel":"Resolved: on version 0.0.1","content":"Array and vararg folding produced fragile fold ranges because the PSI text range does not reliably cover [] or ..., making the anchor points for fold regions unreliable. Arrays and varargs now fold through the same generic-type path as normal types, giving stable ranges and clean compact notation."},{"id":"NL-I7","kind":"issue","title":"Scope Coverage for Declaration-Site Nullability Annotations","status":"Resolved(`0.0.1`)","url":"issues/NL-I7.html","statusLabel":"Resolved: on version 0.0.1","content":"Declaration-site nullability annotations (e.g., @NotNull String foo;) were left outside the fold region, so only the type folded and the placeholder rendered redundant forms like @NotNull String! instead of String!. Declaration-site nullability annotations are now covered by the fold region, so placeholders fold to the clean compact form."},{"id":"NL-I8","kind":"issue","title":"Trailing Whitespace Absorption Before Variable Names","status":"Resolved","url":"issues/NL-I8.html","statusLabel":"Resolved: on version ","content":"Folding swallowed the space before a variable name, producing Array!<Object>var instead of Array!<Object> var. The space before the variable name is now preserved in fold placeholders."},{"id":"NL-I9","kind":"issue","title":"Cross-File Placeholder Cache Pollution","status":"Resolved(`0.0.1`)","url":"issues/NL-I9.html","statusLabel":"Resolved: on version 0.0.1","content":"A single placeholder cache shared across all files caused missing placeholder text when switching between open editor tabs. Placeholder text is now computed on demand, so switching files always shows the correct fold text."},{"id":"NL-I10","kind":"issue","title":"Multidimensional Array Folding Flattening and Misattribution","status":"Resolved(`0.0.1`)","url":"issues/NL-I10.html","statusLabel":"Resolved: on version 0.0.1","content":"Multidimensional arrays (e.g., @NotNull Object @Nullable [] @Nullable []) did not fold into nested structures, and inner-dimension annotations were misattributed. The PSI tree for multidimensional arrays is flat, and searching it returned the leaf component instead of the intermediate dimensions. Multidimensional arrays now fold into correct nested forms, with annotations applied to the right dimensions."},{"id":"NL-I11","kind":"issue","title":"Array Type-Use Annotation Misattribution Strategy","status":"Resolved","url":"issues/NL-I11.html","statusLabel":"Resolved: on version ","content":"It was unclear whether declaration-site annotations on array parameters (e.g., @NotNull Object[]) should apply to the array container itself or to the element type. The behavior is confirmed intentional: declaration-site annotations constrain the array reference itself, while explicit type-use annotations distribute per dimension."},{"id":"NL-I12","kind":"issue","title":"Vararg Fold Range Trailing Space Inconsistency","status":"Resolved(`0.0.1`)","url":"issues/NL-I12.html","statusLabel":"Resolved: on version 0.0.1","content":"Vararg declarations (e.g., Object @Nullable ... arr) swallowed the space preceding the parameter name, unlike standard arrays, due to inconsistent fold-end calculation. Vararg fold ranges no longer swallow the space before the parameter name."},{"id":"NL-I13","kind":"issue","title":"Component Type Annotation Misattribution in Array Dimensions","status":"Resolved(`0.0.1`)","url":"issues/NL-I13.html","statusLabel":"Resolved: on version 0.0.1","content":"Annotations placed on component types (e.g., @NotNull Object @Nullable []) were attributed to the array dimension instead of the component type, failing to yield the correct compact form. Component-type annotations now resolve to the correct position, producing the expected fold output."},{"id":"NL-I14","kind":"issue","title":"Exclusion of Leading Non-Nullability Annotations from Fold Ranges","status":"Resolved(`0.0.1`)","url":"issues/NL-I14.html","statusLabel":"Resolved: on version 0.0.1","content":"When a non-nullability annotation (e.g., @MyAnno) preceded the first nullability annotation (e.g., @NotNull), the leading annotation was left outside the calculated fold range and omitted from the placeholder text — logically correct, but bad on UX. Leading non-nullability annotations are now included in the fold range and preserved in the placeholder text."},{"id":"NL-I15","kind":"issue","title":"Unrecognized Qualified Generic Types and Type Variables","status":"Resolved(`0.0.1`)","url":"issues/NL-I15.html","statusLabel":"Resolved: on version 0.0.1","content":"Types structured like @NotNull Foo.Bar<E> were not recognized as valid parse targets and fell through to an unknown state instead of folding. Nested qualifier references were matched before the full qualified reference, and type variables had no dedicated parsing branch. Qualified generic types and type variables now parse and fold correctly."},{"id":"NL-I16.1","kind":"issue","title":"Resolution Limitation — Annotations Don't Navigate to Declarations, Click Zones Not Refined","status":"Resolved(`0.1.0`)","url":"issues/NL-I16.html#nl-i161-resolution-limitation--annotations-dont-navigate-to-declarations-click-zones-not-refined","statusLabel":"Resolved: on version 0.1.0","content":"The initial navigation implementation had three limitations: annotations navigated to their literal source position instead of their declaration, click-zone detection was too coarse for complex generic types, and preserved non-nullity annotations were completely ignored for navigation. Every visible element in a folded placeholder — type name, ?/! marker, or preserved annotation — now navigates directly to its corresponding declaration."},{"id":"NL-I16.2","kind":"issue","title":"Navigation All-Click-Gives-Same-Target Regression","status":"Resolved(`0.1.1`)","url":"issues/NL-I16.html#nl-i162-navigation-all-click-gives-same-target-regression","statusLabel":"Resolved: on version 0.1.1","content":"After most of NL-I16.1 was fixed, a regression appeared: clicking at any position on a folded placeholder now navigates to the definition of the outer type only — !, ?, type arguments, everything resolves to the same target. Two independent failures: the click-to-token offset mapping was fundamentally wrong (so the first token was always selected), and the tests never verified token-level click resolution. Clicking each part of a folded placeholder now resolves that part's own navigation target, verified by tests on real collapsed fold regions."},{"id":"NL-I16.3","kind":"issue","title":"Keyboard-Only Navigation (F12) Lacks Precise Token Targeting for IDEAVim Users","status":"Ditched(IdeaVim always expands folded text on caret movement — no navigation issue exists)","url":"issues/NL-I16.html#nl-i163-keyboard-only-navigation-f12-lacks-precise-token-targeting-for-ideavim-users","statusLabel":"Ditched: because \"IdeaVim always expands folded text on caret movement — no navigation issue exists\"","content":"Keyboard-only caret movement within a collapsed fold cannot determine which character of the placeholder the cursor is \"on\", because the underlying document offset is always the fold start. However, this turned out to be a non-issue for IdeaVim users and was ditched."},{"id":"NL-I16.4","kind":"issue","title":"Generic Type Arguments Cannot Be Navigated Independently","status":"Resolved(`0.1.2`)","url":"issues/NL-I16.html#nl-i164-generic-type-arguments-cannot-be-navigated-independently","statusLabel":"Resolved: on version 0.1.2","content":"When clicking on a type argument inside a generic fold placeholder (e.g., Foo in Map!<Foo?, Bar!>), navigation always falls back to the outermost type (Map's class declaration). The resolver unconditionally resolved the outermost reference, and no logic mapped a type-token position to a specific type argument in the PSI. Clicking a type argument now navigates to its own declaration instead of the outermost enclosing type."},{"id":"NL-I16.5","kind":"issue","title":"Suffix-Adjacent Delimiter Click Gap (UX)","status":"Resolved(`0.1.3`)","url":"issues/NL-I16.html#nl-i165-suffix-adjacent-delimiter-click-gap-ux","statusLabel":"Resolved: on version 0.1.3","content":"For placeholders like Uni!<Foo>, clicking on < (placeholder offset 4) returns no navigation target because the delimiter has no target of its own. Delimiters adjacent to a nullity suffix now delegate to the suffix token, and a status-bar hint guides the user when no prefix delegation is possible."},{"id":"NL-I16.6","kind":"issue","title":"CaretListener Tramples MouseAdapter's PlaceholderClickInfo","status":"Resolved(`0.1.4`)","url":"issues/NL-I16.html#nl-i166-caretlistener-tramples-mouseadapters-placeholderclickinfo","statusLabel":"Resolved: on version 0.1.4","content":"After the visual-position capture architecture was implemented, Ctrl+clicking at any position within the folded text always navigates to the type's class declaration. On the same UI turn, the mouse press and the caret positioning it triggers both fire — and the caret listener unconditionally overwrote the click info with a wrong value. Mouse and caret capture now write to separate keys, so neither can overwrite the other's data and click positions resolve correctly."},{"id":"NL-I16.7","kind":"issue","title":"Smart filling: This will be the final!!!","status":"Resolved(`0.1.5`)","url":"issues/NL-I16.html#nl-i167-smart-filling-this-will-be-the-final","statusLabel":"Resolved: on version 0.1.5","content":"Case: Type! → Try \"Go Definition\" at the right of ! → falls back to Type's navigation. The position-tracking listeners were installed too late — inside the navigation handler itself, after the click had already been dispatched — so the first navigation in an editor had no captured click position. Position tracking is installed eagerly for every new editor, right-edge clicks on a marker resolve correctly, and listeners are properly stored and cleaned up."},{"id":"NL-I16.8","kind":"issue","title":"Qualifier Segments Lose Navigation in Qualified References","status":"Resolved(`1.0.0`)","url":"issues/NL-I16.html#nl-i168-qualifier-segments-lose-navigation-in-qualified-references","statusLabel":"Resolved: on version 1.0.0","content":"[!BUG] After the segment-driven navigation rewrite removed hardcoded handling, the qualifier part of a folded qualified type — Map in Map.Entry — no longer navigates anywhere, while Entry still jumps to its declaration. The fold-time segment map only records a navigation anchor for the identifier of a qualified type, so the qualifier text renders as a no-target literal. [!CHECK] Clicking the qualifier part of a folded qualified type now navigates to the qualifier class — Map in Map.Entry jumps to java.util.Map, while Entry keeps navigating to the nested class."},{"id":"NL-I17","kind":"issue","title":"Back to `IrNode`: Refocus on Intersection","status":"Resolved(`0.1.6`)","url":"issues/NL-I17.html","statusLabel":"Resolved: on version 0.1.6","content":"Intersection types existed in the folding engine's internal model, but their folding was barely tested and could not be seen working in a real IDE — only the internal representation was verified, never the actual fold in the editor. Intersection types in cast expressions now fold correctly in the editor, including those carrying nullability annotations and wildcards."},{"id":"NL-I18","kind":"issue","title":"Config Sync Redesign — On-Demand Registry/Pipeline Re-creation","status":"Resolved(`0.4.1`)","url":"issues/NL-I18.html","statusLabel":"Resolved: on version 0.4.1","content":"The folding engine recreated its annotation registry and processing pipeline from scratch on every fold build, which is wasteful and becomes increasingly expensive as the plugin's configuration grows. The registry and pipeline were treated as short-lived per-build objects instead of long-lived components that react to configuration changes. The registry and pipeline are now created once and only recreated when the configuration actually changes, reducing overhead during editing and repaints."},{"id":"NL-I19.1","kind":"issue","title":"Qualified Types' Incorrect Folding Result","status":"Resolved(`0.2.1`)","url":"issues/NL-I19.html#nl-i191-qualified-types-incorrect-folding-result","statusLabel":"Resolved: on version 0.2.1","content":"A.@NotNull B folded to the broken A.A.B! — the leading qualifier A. stayed visible outside the fold and was duplicated — while @NotNull A.B folded correctly. The fold range started at the annotation instead of the start of the type element, leaving the leading qualifier outside the fold and duplicating it in the rendered result. Qualified types with an annotation between the qualifier and identifier now fold correctly, with the fold range covering the whole type."},{"id":"NL-I19.2","kind":"issue","title":"Qualified Type Annotation Resolution Misses Annotations on Intermediate Qualifier Segments","status":"Resolved(`0.2.2`)","url":"issues/NL-I19.html#nl-i192-qualified-type-annotation-resolution-misses-annotations-on-intermediate-qualifier-segments","statusLabel":"Resolved: on version 0.2.2","content":"A type-use nullability annotation on an intermediate qualifier segment of a deeply qualified type (e.g., A.@NotNull B.C) produced no folding at all for the whole type. The pipeline could only see annotations placed directly on the type element; annotations buried inside the qualified-reference chain were invisible, and the qualifier text kept annotation markup — so such types fell through to \"no fold\". Nullability annotations on any segment of a qualified type are now resolved, and such types fold correctly — e.g., A.@NotNull B.C → A.B.C!, A.@Nullable B.C → A.B.C?."},{"id":"NL-I20","kind":"issue","title":"Class/package scope-default nullability does not propagate to type arguments and array components","status":"Resolved(`0.3.1`)","url":"issues/NL-I20.html","statusLabel":"Resolved: on version 0.3.1","content":"When a scope-default annotation such as @NotNullByDefault is applied to a class or package, the type arguments of generic types and the component types of arrays are expected (per @NotNullByDefault's Javadoc) to inherit the scope default as well. Currently, Nullify only resolves scope defaults at the top-level type-use position — type arguments like List<@Nullable Foo> in a @NotNullByDefault class are treated as unannotated rather than implicitly @NotNull. The scope default was resolved only at the outermost type position; type arguments and array components were resolved in isolation and never consulted the class/package default. Scope-default nullability now propagates into type arguments, array components, and wildcard bounds — unless an explicit annotation on the parent type overrides it."},{"id":"NL-I21","kind":"issue","title":"Configurable Wildcard Symbol & Settings UI I18n","status":"Resolved(`0.5.0`)","url":"issues/NL-I21.html","statusLabel":"Resolved: on version 0.5.0","content":"Wildcards were always folded using * for unbounded wildcards (e.g. ? → *). This behavior should be user-configurable to allow choosing between * and ?. Additionally, the settings UI text lacked internationalization (i18n) support — all UI strings in the configuration panel should be localizable. The unbounded-wildcard symbol is now user-configurable (? or *, default ?), and the settings UI is fully localized."},{"id":"NL-I22","kind":"issue","title":"Settings Change Does Not Refresh Existing Fold Regions","status":"Resolved(`0.8.0`)","url":"issues/NL-I22.html","statusLabel":"Resolved: on version 0.8.0","content":"When the user changes folding behavior settings in Settings → Editor → Nullify (e.g., toggling Kotlin-style nullity markers, disabling nullity folding, switching the wildcard symbol, or modifying the custom annotation registry), existing fold regions in open editors display stale placeholder text based on the old configuration. Applying settings recreated the folding engine but never told the open editors to rebuild their folds, so existing fold regions kept their old placeholder text. After applying settings, all open editors immediately display fold regions with the new placeholder text — no reopening or manual re-fold required."},{"id":"NL-I23","kind":"issue","title":"Inconsistent QuickFix Display Order Across Minority/Majority Annotations","status":"Resolved(`0.8.2`)","url":"issues/NL-I23.html","statusLabel":"Resolved: on version 0.8.2","content":"When annotations from different nullability namespaces are present in the same file, the inspection's quick fixes show different options depending on the element the user clicks: Minority annotation (e.g., @lombok.NonNull when the majority uses @javax.annotation.Nonnull): Shows \"Replace with @javax.annotation.Nonnull\"Shows \"Set @javax.annotation.Nonnull as project @NotNull default\"Majority annotation (e.g., @javax.annotation.Nonnull itself): Shows \"Remove annotation\" (if it's a per-element duplicate on the SAME element as another mark)Shows \"Set @javax.annotation.Nonnull as project @NotNull default\" (if it causes no conflict by itself)This asymmetry is confusing — the majority annotation user might not understand why \"Replace\" doesn't appear, while the minority user gets both Replace + SetDefault. The quick-fix pool was built per-annotation, so each annotation offered a different set of fixes depending on whether it was the majority or the minority — instead of a single symmetric fix list per scenario. Flagging and quick fixes are now order-independent and symmetric: exactly the inconsistent (non-majority / non-default) annotations are flagged, each offering the same quick-fix set regardless of which annotation the user clicks."},{"id":"NL-I24","kind":"issue","title":"`inspection.inconsistent.nullability.message` Not Following IDE Language","status":"Resolved(`0.8.0`)","url":"issues/NL-I24.html","statusLabel":"Resolved: on version 0.8.0","content":"All other Nullify i18n keys (settings UI labels, etc.) correctly follow the IDE's display language (e.g., 简体中文). However, the inspection's display name inspection.inconsistent.nullability.display.name always rendered as English text, because it was hardcoded in plugin.xml as displayName=\"Inconsistent nullability annotation\" which took precedence over the bundle-based i18n. The inspection's display name was hardcoded in plugin.xml, so the platform always used that English text and never consulted the localized message bundles. The inspection's display name now follows the IDE's display language instead of always showing English."},{"id":"NL-I25","kind":"issue","title":"Scope-Level Override Anti-Design — `ScopeEntry(scopeName, fqcn)` Mapping","status":"Resolved(`0.8.1`)","url":"issues/NL-I25.html","statusLabel":"Resolved: on version 0.8.1","content":"The project-level config used a per-name override model that let users map specific class/package names to specific annotation FQCNs (e.g. com.example.Foo=some.Annotation). This was an anti-design — the original intent was a single global FQCN per scope level: Element-Level @Nullable/@NotNull — annotations on parameters, return values, fields, locals, type-use positions.Class-Level @Nullable/@NotNull — scope defaults such as @NotNullByDefault on a class.Package-Level @Nullable/@NotNull — scope defaults such as @ParametersAreNonnullByDefault in package-info.java. The config stored a list of per-name FQCN mappings for class/package overrides, adding a layer of per-name complexity that was neither intended nor meaningful. Nullability default annotations are now configured independently for three scope levels (Element, Class, Package), each with a single global @Nullable/@NotNull FQCN — the confusing per-name override mapping is gone."},{"id":"NL-I26","kind":"issue","title":"QuickFix Standards Conformance — `InconsistentNullabilityInspection`","status":"Resolved(`0.8.2`)","url":"issues/NL-I26.html","statusLabel":"Resolved: on version 0.8.2","content":"The inspection's quick fixes did not always match the intended standard for each scenario: the fix set differed depending on which annotation was clicked, three or more conflicting annotations on one element were not handled, and incremental analysis produced inconsistent flagging decisions. Quick-fix pools were built per-annotation based on that annotation's relationship to the canonical one, producing asymmetric fix lists; removals assumed a small fixed set of annotations; and incremental analysis could base decisions on stale state. An \"Aggressive analysis\" toggle lets the inspection re-analyze the whole file (default) or only the edited region (Prudence mode). Flagging is now order-independent and symmetric — exactly the inconsistent annotations are flagged, each with the same quick-fix set — and three or more conflicting annotations on one element are each flagged and individually removable."},{"id":"NL-I27","kind":"issue","title":"Annotation Picker Candidates Display Bare FQCN — Should Show `simpleName (package)`","status":"Resolved(`0.9.1`)","url":"issues/NL-I27.html","statusLabel":"Resolved: on version 0.9.1","content":"In the annotation FQCN completion popup, every candidate is rendered as the full FQCN (e.g. org.jetbrains.annotations.Nullable). The idiomatic IntelliJ presentation is the simple name followed by its package (rendered as a gray tail text): Nullable org.jetbrains.annotations i.e. ${simple_name} ${package_name}, where the tail is the FQCN with the simple name itself removed (package only). Long library FQCNs are then much easier to scan, and the annotation family (JetBrains / Jakarta / Lombok / …) becomes visible at a glance. The completion descriptor rendered the bare FQCN because only the insert string was defined — the display hooks that render the item text and type text were never overridden. The picker now renders candidates as simpleName with the package as a gray tail text (e.g. Nullable org.jetbrains.annotations), while the inserted value stays the full FQCN."},{"id":"NL-I28.1","kind":"issue","title":"Uppercase First Typed Character Yields No Completion Candidates","status":"Resolved(`0.9.2`)","url":"issues/NL-I28.html#nl-i281-uppercase-first-typed-character-yields-no-completion-candidates","statusLabel":"Resolved: on version 0.9.2","content":"In any annotation FQCN completion field, if the first character typed is uppercase (e.g. N), the popup shows no candidates at all. Typing the same letter lowercase (e.g. n) works and shows suggestions. The provider deliberately returned a null prefix matcher so the platform would not drop simple-name hits — but with no matcher, the completion session re-filtered candidates with its own case-sensitive matcher built from the typed prefix, which dropped every uppercase-first candidate. Typing an uppercase first character now yields the same suggestions as the lowercase form."},{"id":"NL-I28.2","kind":"issue","title":"Completion Inserts Without Replacing the Typed Prefix and Loses Match Highlighting","status":"Resolved(`0.9.4`)","url":"issues/NL-I28.html#nl-i282-completion-inserts-without-replacing-the-typed-prefix-and-loses-match-highlighting","statusLabel":"Resolved: on version 0.9.4","content":"After the NL-I28.1 fix, accepting a completion in any annotation FQCN field no longer replaces the typed prefix and the typed prefix is never highlighted in the popup candidates. The always-true matcher used to fix NL-I28.1 has an empty prefix, and the platform derives both the text-to-replace and the highlight from that matcher's prefix — so nothing was replaced and nothing was highlighted. Accepting a completion now replaces the typed prefix, and the typed prefix is highlighted in the suggestion list again."},{"id":"NL-I29","kind":"issue","title":"Project-Default FQCN Fields Collapsed Height, Not Focusable, Not Editable","status":"Resolved(`0.9.3`)","url":"issues/NL-I29.html","statusLabel":"Resolved: on version 0.9.3","content":"The 6 project-default annotation FQCN input fields (Settings → Editor → Nullify Element/Class/Package-Level Defaults → @Nullable/@NotNull) render with a collapsed height — nearly as thin as a progress bar — cannot be clicked / focused, and cannot accept typed text. The registry-table \"+\" dialogs (which also use the completion field, but inside a DialogWrapper) are unaffected; only the inline project-default section fields are broken. The completion field's preferred size was pinned to its pre-realization height — which reports a minimal value before the embedded editor exists — so the row collapsed and the field became non-interactive. The six project-default fields render at a normal height and can be clicked, focused, and typed into again."},{"id":"NL-I30","kind":"issue","title":"`ClassCastException` in `determineScope` on Mid-Typing Type-Use Annotations","status":"Resolved(`0.9.5`)","url":"issues/NL-I30.html","statusLabel":"Resolved: on version 0.9.5","content":"While typing a field declaration whose type carries a type-use nullability annotation, e.g. The scope classifier blindly cast the annotation's owner to a modifier list. During mid-typing / incomplete-parse states the owner can be some other runtime type, so the cast threw and aborted the whole file's inspection. The inspection no longer crashes while typing such fields, and flagging completes for the whole file even when one annotation is malformed mid-typing."},{"id":"NL-I31.1","kind":"issue","title":"`@NotNull var` folds to `Map<Set<String>, Pair<Integer, Double>>!` despite nullify-style configuration","status":"Resolved(`0.9.6`)","url":"issues/NL-I31.html#nl-i311-notnull-var-folds-to-mapsetstring-pairinteger-double-despite-nullify-style-configuration","statusLabel":"Resolved: on version 0.9.6","content":"@NotNull var is folded to Map<Set<String>, Pair<Integer, Double>>! — the ! is appended at the very end of the fully-expanded inferred type — with kotlin-style markers disabled. In nullify style the suffix should hug the outer type name (Map!<Set<String>, Pair<Integer, Double>>); only kotlin style renders a trailing suffix. The var branch never reparsed the inferred type as a real annotated type element, so the nullity mark was applied against an assumed single-node structure and the suffix ended up trailing the whole expanded type instead of being re-placed per the configured style. Folded var locals now place the marker correctly in Nullify style — hugging the outer type name — while Kotlin style keeps its trailing marker."},{"id":"NL-I31.2","kind":"issue","title":"Navigation on folded `var` placeholder is broken","status":"Resolved(`0.9.7`)","url":"issues/NL-I31.html#nl-i312-navigation-on-folded-var-placeholder-is-broken","statusLabel":"Resolved: on version 0.9.7","content":"On the same folded @NotNull var placeholder, navigation misbehaves: the ! (caret placed after the !; before the ! does nothing) navigates to the declaration of Map, and every other position provides no navigation. The placeholder is built from the inferred type, but navigation resolves tokens against the raw var type element — whose structure is just a bare var keyword — so the token-to-PSI mapping never lines up. Ctrl+clicking a folded annotated var placeholder now navigates like any explicit type — the type name and type arguments jump to their declarations, and the marker jumps to the nullability annotation."},{"id":"NL-I32.1","kind":"issue","title":"Generic-method `var` — Right-Edge Navigation Gap on Method Type Parameters","status":"Resolved(`0.9.8`)","url":"issues/NL-I32.html#nl-i321-generic-method-var--right-edge-navigation-gap-on-method-type-parameters","statusLabel":"Resolved: on version 0.9.8","content":"In a generic method, a var declared with a nullability annotation whose inferred type is (or contains) a method type parameter navigates fine on the type parameters themselves, but the caret positioned to the right of a type parameter cannot jump — the same UX-gap class as NL-I16.5. A delimiter or whitespace immediately following a type argument maps to a token that returns no targets and is never delegated back to the type argument — the NL-I16.5-style gap persists on the type-argument side. The click-zone gap to the right of type arguments is closed: positioning the caret on a delimiter or whitespace that immediately follows a type argument now navigates to that type argument's declaration — E, and V> behave exactly like E and V."},{"id":"NL-I32.2","kind":"issue","title":"No-Target Navigation Silently Fails and Unfolds","status":"Resolved(`0.9.9`)","url":"issues/NL-I32.html#nl-i322-no-target-navigation-silently-fails-and-unfolds","statusLabel":"Resolved: on version 0.9.9","content":"When the user Ctrl+Clicks (or F12/Ctrl+B) on a folded placeholder position that has no resolvable navigation target, the current behavior is a silent failure combined with the fold text being unfolded: The handler returns null — silent fail, no feedback.IntelliJ's default Ctrl+click behavior on a collapsed fold region then expands the fold, replacing the placeholder with the full verbose source.Desired behavior: cancel the unfold and let IntelliJ show its native \"cannot find declaration to go to\" guidance (the status-bar hint shown for failed goto-declaration), instead of silently expanding the folded text. An empty target list is reported as the standard \"decline\" signal, so the platform runs its default goto-declaration on the underlying source — which, on a collapsed fold region, expands the fold. No feedback tells the user that Nullify recognized the placeholder but could not resolve a target. No-target navigation is no longer a silent failure that unfolds the fold: the Ctrl/Cmd+click release is consumed before the platform expands the fold, so the fold stays collapsed with no visible fold/unfold flicker, and IntelliJ shows its native \"cannot find declaration to go to\" guidance when nothing can be resolved."},{"id":"NL-I33","kind":"issue","title":"Annotation Picker Hardcodes `AllIcons.Nodes.Annotationtype` — Custom Icon Plugins Ignored","status":"Resolved(`0.9.10`)","url":"issues/NL-I33.html","statusLabel":"Resolved: on version 0.9.10","content":"The annotation picker's completion popup renders every candidate with a hardcoded stock annotation glyph. Under a stock IntelliJ this matches the platform's own rendering, but when the user installs an icon plugin that customizes annotation icons, the picker keeps showing the stock glyph while every other IDE surface (Project View, Structure View, standard code completion) shows the plugin's icon — the picker no longer matches the user's icon theme. The picker bypassed the platform's PSI-based icon resolution and returned a hardcoded icon, and the candidate model dropped the resolved annotation class it could have asked for an icon. The annotation picker's icons now follow the IDE's icon theme. Each candidate is rendered with the icon the platform resolves for its annotation class, so custom icon plugins that restyle annotation glyphs are honored in the completion popup — exactly like the project view and standard code completion. The stock annotation icon remains as a fallback when an annotation cannot be resolved (e.g. during indexing or without a JDK)."},{"id":"NL-I34","kind":"issue","title":"Keyboard (F12/Ctrl+B) Navigation Can't Reach Interior Placeholder Tokens on Collapsed Folds","status":"Resolved(`0.9.10`)","url":"issues/NL-I34.html","statusLabel":"Resolved: on version 0.9.10","content":"Mouse Ctrl+Click navigation on a folded type can target every placeholder token, but keyboard-only navigation (F12 / Ctrl+B) on the same collapsed fold was reported to reach only the first or the last token. In EnumMap!<E, V>, placing the caret with arrow keys and pressing F12 navigated to the outer EnumMap when the caret sits at the fold's left edge, and to the last token when it sits at the fold's right edge — the type arguments E/V and the ! marker appeared unreachable. (This symptom is no longer reproducible after the CaretListener refactor; the original premise — that moving the caret inside a collapsed fold expands it — is incorrect. See the corrected Root Cause.) The previously recorded root cause was wrong: moving the caret inside a collapsed fold does not expand the text in the standard IDE — expanding folded text on caret movement is an IdeaVim-only behavior (see NL-I16.3). In the normal editor, arrow-key movement never expands a collapsed fold, and the caret's visual position can rest on any interior column of the placeholder, so every placeholder token is addressable from the keyboard. The reported symptom is no longer reproducible after the CaretListener refactor. Keyboard navigation on a collapsed fold now resolves every placeholder token correctly: the caret can walk through the placeholder interior without unfolding the text (that unfold-on-caret-move behavior is IdeaVim-specific), so F12 / Ctrl+B from an interior caret position reaches the corresponding type, type argument, or ?/! marker exactly like Ctrl+Click. The reported symptom is no longer reproducible."},{"id":"NL-I35","kind":"issue","title":"Navigation on Folded Annotation Arguments Jumps to the Type Instead of the Annotation's Element Methods","status":"Resolved(`1.0.0`)","url":"issues/NL-I35.html","statusLabel":"Resolved: on version 1.0.0","content":"When a non-nullity annotation with arguments (e.g. @MyAnno(name = \"foo\", value = \"bar\")) is preserved inside a folded placeholder such as @MyAnno(name = \"foo\", value = \"bar\") Foo!, clicking on the annotation-argument part navigates to the field's type (Foo) instead of the annotation's element methods (MyAnno#name() / MyAnno#value()). Only the annotation name itself (@MyAnno) navigates correctly. The placeholder parser does not understand annotation argument lists. Inside @MyAnno(name = \"foo\", value = \"bar\") the characters (, ), =, and \" are treated as unknown and skipped, while the argument names and values (name, foo, value, bar) are misclassified as type names. Clicking them therefore resolves to the field's type instead of the annotation's element methods. Clicking an annotation argument inside a preserved annotation on a folded type now navigates to the annotation's element method — e.g. name and value in @MyAnno(name = \"foo\", value = \"bar\") String! jump to MyAnno#name() and MyAnno#value() — instead of the field's type. This is delivered by the PSI-anchored fold-navigation redesign in NL-F12."},{"id":"NL-I36","kind":"issue","title":"`final` Modifier Swallowed When Folding `@Nullable final var` / `@Nullable final String`","status":"Resolved(`1.0.0`)","url":"issues/NL-I36.html","statusLabel":"Resolved: on version 1.0.0","content":"When a nullability annotation is written before a modifier keyword — e.g. @Nullable final var foo = ... or @Nullable final String foo — folding collapses the declaration to String? foo, silently dropping the final keyword. The folded line should read final String? foo. The same loss happens with any modifier keyword placed between a declaration annotation and the type (e.g. @Nullable static String, @Nullable public String). The fold region must span from the earliest declaration annotation (which sits before the modifier keyword) to the type element, and a fold region is one contiguous text range. Because the placeholder replaces that whole range, every modifier keyword inside it is erased unless the renderer explicitly reproduces it. Modifier keywords written between a declaration nullability annotation and the type are now preserved inside the folded placeholder, so @Nullable final var foo = ... folds to final String? foo and @Nullable static String foo folds to static String? foo. The fold range still spans the annotation through the type, and navigation behavior is unchanged."},{"id":"NL-I37","kind":"issue","title":"Auto-Collapse (NL-F14) Fails in Real IDE — Races the Async Fold Pass","status":"Resolved(`1.0.0`)","url":"issues/NL-I37.html","statusLabel":"Resolved: on version 1.0.0","content":"The \"auto-collapse Nullify folds after project analysis completes\" behavior worked in unit tests but had no effect in a real IDE: after indexing finished, the Nullify folds stayed expanded instead of collapsing automatically. The collapse was triggered at the exact moment analysis finished, but the fold regions Nullify creates are actually materialized by the IDE a moment later, on a background pass. The collapse ran before they existed — or was silently overwritten by that very pass, which creates new folds expanded by default. Nullify folds now collapse reliably after project analysis in a real IDE, while folds the user expands manually stay expanded."},{"id":"NL-I38","kind":"issue","title":"`Slow operations are prohibited on EDT` When Typing a Reason in a Nullability Annotation","status":"Resolved(`1.0.0`)","url":"issues/NL-I38.html","statusLabel":"Resolved: on version 1.0.0","content":"While typing a reason string inside a nullability annotation (e.g. @Nullable(\"\")), just after the opening quote — when the value is still an empty string — Nullify throws an java.lang.Throwable: Slow operations are prohibited on EDT error into the log, triggered from the hint manager re-rendering the collapsed fold. Every time a fold collapses the hint manager re-runs the full folding pipeline to read the annotation's reason — and that pipeline resolves the type (a slow, index-backed operation). When it runs on the UI thread (which inlays require), the IDE flags it as a slow operation on the EDT and reports the error. The Slow operations are prohibited on EDT error is gone. The hint manager no longer re-runs the folding pipeline to read an annotation's reason: it now resolves the reason through a lightweight, index-free path, so merely typing a nullability annotation — even one without a reason — never triggers slow type/index work on the UI thread."},{"id":"NL-I39","kind":"issue","title":"Reason Hint Block Inlay Not Aligned With the Fold — Should Align to the Next Line's First Visible Character","status":"Resolved(`1.0.0`)","url":"issues/NL-I39.html","statusLabel":"Resolved: on version 1.0.0","content":"The nullability reason hint shown above a collapsed fold does not line up with the fold itself — its left edge is offset from where the folded placeholder sits. The best UX is to align the hint's left edge with the first visible character of the next line, so the hint reads as an annotation attached to that line. A block inlay is anchored to a document offset, not to a visual column. The current placement anchors the inlay at the fold's start offset (region.startOffset) and lets the editor decide the horizontal origin, which does not coincide with the folded placeholder's visual column or the next line's content indentation. The nullability reason hint now lines up with the declaration it belongs to: its left edge aligns with the first visible (non-whitespace) character of the folded line below it, so it reads as an annotation attached to that line instead of hugging the editor's left edge. The alignment follows horizontal scrolling."},{"id":"NL-I40.1","kind":"issue","title":"CJK Reason Hint Crashes With `NoSuchElementException` When No Configured Font Can Display the First Character","status":"Resolved(`1.0.0`)","url":"issues/NL-I40.html#nl-i401-cjk-reason-hint-crashes-with-nosuchelementexception-when-no-configured-font-can-display-the-first-character","statusLabel":"Resolved: on version 1.0.0","content":"In a Chinese-locale IDE, collapsing a fold whose reason begins with a CJK character made the hint disappear and the IDE log the error java.util.NoSuchElementException: Collection contains no element matching the predicate from ReasonHintInlayRenderer. The fallback renderer selected the first font in the chain that can display the sentence's first character with fonts.first { it.canDisplay(text[0]) }. When the sentence starts with a CJK glyph that neither the editor's base font nor FontPreferences.getEffectiveFontFamilies can display — the scheme does not always carry a CJK font — the predicate matches nothing and .first throws. The hint now always appears: the font selection falls back gracefully when no configured font can display a character, and the JDK's logical Monospaced font is appended as a guaranteed fallback — it carries the platform's composite font chain, so CJK reasons render real glyphs even when the scheme has no CJK font of its own."},{"id":"NL-I40.2","kind":"issue","title":"Reason Hint Renders CJK Text as Tofu Blocks","status":"Resolved(`1.0.0`)","url":"issues/NL-I40.html#nl-i402-reason-hint-renders-cjk-text-as-tofu-blocks","statusLabel":"Resolved: on version 1.0.0","content":"When the nullability reason contains Chinese (or other CJK) characters, the hint above the collapsed fold displays them as tofu/placeholder blocks (□□□) instead of the actual glyphs. Latin text renders fine. The hint renderer paints text with a raw AWT Font resolved from the editor color scheme, which does not carry the IDE's CJK font-fallback chain. The IDE normally renders mixed-script editor text through its own fallback-aware text layout; bypassing that with Graphics.drawString loses the CJK fallback font, so unsupported glyphs come out as boxes. Chinese (and other CJK) characters in a nullability reason now render as real glyphs instead of □□□ tofu blocks. Both the measured width and the painted text go through the editor's font-fallback chain, so mixed-script reasons look exactly as they would in the editor itself."},{"id":"NL-I41","kind":"issue","title":"Reason Hint Should Render in a Gray/Muted Color by Default","status":"Resolved(`1.0.0`)","url":"issues/NL-I41.html","statusLabel":"Resolved: on version 1.0.0","content":"The nullability reason hint above a collapsed fold currently renders in the editor's full-strength default foreground color, making it look like actual code. It should instead render in a gray/muted color — the same hint styling other IDE inline hints use — so it is visually subordinate to the real code. The hint renderer hard-codes the editor's default foreground color for its painted text, with no reference to a hint/annotation color scheme key. The reason hint now renders in the editor's normal foreground by default, and users who want it muted can theme it under Settings → Editor → Color Scheme → Nullify — no longer stuck with an overly dark gray. The color follows light/dark scheme switches automatically and applies to every open editor immediately."},{"id":"NL-I42.1","kind":"issue","title":"Color Scheme Effects and Bold/Italic Not Applied in the Editor","status":"Resolved(`1.0.0`)","url":"issues/NL-I42.html#nl-i421-color-scheme-effects-and-bolditalic-not-applied-in-the-editor","statusLabel":"Resolved: on version 1.0.0","content":"In Settings → Editor → Color Scheme → Nullify, the \"Reason hint\" attribute previews effects (strikethrough, underline, wave, …) and bold/italic correctly, but in the actual editor the hint ignores all of them — it always renders plain with only the foreground color applied. The hint's inlay renderer reads only the foreground color from the scheme attribute and never applies the attribute's font style, background, or effects."},{"id":"NL-I42.2","kind":"issue","title":"Overlong Reason Text Overflows Horizontally — No Wrapping; Default Max-Inline Length Too Small","status":"Resolved(`1.0.0`)","url":"issues/NL-I42.html#nl-i422-overlong-reason-text-overflows-horizontally--no-wrapping-default-max-inline-length-too-small","statusLabel":"Resolved: on version 1.0.0","content":"A very long reason, once expanded, is laid out as a single unbounded line and runs off the right edge of the screen — it never wraps to the next line. Separately, the default max-inline length (40) is small, so ordinary reasons collapse prematurely; the sensible default is 80, dynamically scaled by the user's editor font size. The hint's wrap width is computed from the editor's full content component width instead of the visible viewport, so when the file is wider than the window the wrap point lands off-screen and nothing wraps. The collapse threshold is a fixed character count that ignores the editor's font size."},{"id":"NL-I42.3","kind":"issue","title":"Long Hint Has No Fold Arrow in the Gutter","status":"Resolved(`1.0.0`)","url":"issues/NL-I42.html#nl-i423-long-hint-has-no-fold-arrow-in-the-gutter","statusLabel":"Resolved: on version 1.0.0","content":"When a long reason is shown as a multi-line hint, there is no fold arrow in the editor gutter next to it, so the only way to collapse it back is to click the text — users expect the standard IDE fold arrow beside the hint. The hint renderer never provides a gutter icon renderer, so the platform shows nothing in the gutter for the block inlay."},{"id":"NL-I43","kind":"issue","title":"Reason Hint Does Not Appear After the Comment-Maybe-Reason Migration (NL-F21)","status":"Resolved(`1.0.0`)","url":"issues/NL-I43.html","statusLabel":"Resolved: on version 1.0.0","content":"After applying Migrate comment to annotation reason (NL-F21) to a collapsed declaration — e.g. // Foo\nfinal @NotNull var carryIDBox = context.carryID; becomes final @NotNull(\"Foo\") var carryIDBox = context.carryID; — the reason hint that NL-F16 renders above collapsed Nullify folds does not appear. The hint only shows after a manual round-trip: clicking the folded text expands the fold, the fold collapses again on its own a moment later, and only then does the hint appear; a second click expands it for good. The expected behavior is that the hint shows immediately after the migration, without any manual interaction. Migrating the comment writes inside the folded region, and the IDE's next folding pass keeps the fold exactly as it was — its range shifts to the new annotation text, the placeholder stays the same — so the pass is a no-op as far as folding is concerned and the event that normally refreshes the hint never fires. The hint therefore only appeared after a manual expand/re-collapse round-trip, and the auto-collapse identified folds by their position, so once the migration moved the fold's position it looked brand-new and fought the user's expand. The reason hint now appears right after migrating a comment into an annotation reason — as soon as the IDE finishes recomputing the fold — with no manual expand/re-collapse round-trip, and expanding the fold manually is never undone by the auto-collapse."},{"id":"NL-I44","kind":"issue","title":"Reason Hint Extraction Resolves Annotations on the EDT — \"Slow operations are prohibited on EDT\" Errors","status":"Resolved(`1.0.0`)","url":"issues/NL-I44.html","statusLabel":"Resolved: on version 1.0.0","content":"In a real project, the IDE log gets flooded with Slow operations are prohibited on EDT errors (plus a Should be called at least in the state COMPONENTS_LOADED cascade) while Nullify reason hints (NL-F16) are shown above collapsed folds. The violations point into Nullify's hint code — the fold's reason is being resolved with index access on the UI thread. Every collapsed fold re-reads its annotation's reason on the UI thread after each folding pass, and reading an annotation's fully qualified name forces the IDE to resolve the annotation class through the project index — which the platform forbids on the UI thread. The hint code assumed this resolution was index-free, but annotation names are class-name references and cannot be qualified without resolving them. The reason extraction behind a collapsed fold's hint now runs on a background thread, so writing or folding nullability annotations no longer performs index resolution on the UI thread — the Slow operations are prohibited on EDT errors are gone."},{"id":"NL-I45","kind":"issue","title":"Trailing Comment on the Declaration Line Not Recognized by the Comment-Migration Intention (NL-F21)","status":"Resolved(`1.0.0`)","url":"issues/NL-I45.html","statusLabel":"Resolved: on version 1.0.0","content":"[!BUG] Migrate comment to annotation reason does not fire for a trailing comment that closes the whole declaration line rather than sitting directly right of the annotation. When the comment comes after the declaration's last token — e.g. final @NotNull var foo = \"\";// Assigned with a literal value. — the intention is not offered at all. The migration only recognizes comments directly adjacent to the annotation (@NotNull // reason) or on the line above it. The expected behavior is that a comment trailing the declaration on the same physical line migrates into the annotation's reason just like any other adjacent comment. [!SEARCH] The intention only looks for comments immediately next to the annotation; a comment at the end of the declaration line sits after the type and initializer, so the adjacency check never reaches it. [!CHECK] A comment that trails a single-line declaration — fields, local variables and methods alike — is now recognized: the intention fires both at the annotation and on the trailing comment itself, and the comment migrates into the annotation's reason."},{"id":"NL-I46","kind":"issue","title":"IndexNotReadyException When Opening Settings During Project Indexing","status":"Resolved(`1.0.0`)","url":"issues/NL-I46.html","statusLabel":"Resolved: on version 1.0.0","content":"[!BUG] Opening Settings → Editor → Nullify right after the IDE starts — while the project is still indexing — logged an IndexNotReadyException (\"Please change caller according to com.intellij.openapi.project.IndexNotReadyException documentation\"). The annotation completion was also broken during indexing: the suggestion popup produced error logs and the annotation icons could not be resolved. [!SEARCH] The annotation-candidate search relies on the IDE's class index, which is unavailable while indexing is in progress. The search ran on a background thread without waiting for indexing to finish; the platform throws an exception instead of returning an empty result in that state, and the exception escaped into the IDE log. [!CHECK] Opening Settings while the project is indexing no longer produces any exception. During indexing the annotation fields simply show no suggestions and the stock annotation icon; once indexing finishes, the cache is primed and completion works as usual."},{"id":"NL-I47","kind":"issue","title":"Modal Settings Mode Stacks Two Settings Dialogs When Clicking Welcome-Panel Section Titles","status":"Open","url":"issues/NL-I47.html","statusLabel":"Open","content":"[!BUG] In the legacy modal Settings mode (when ide.ui.non.modal.settings.window=false), clicking one of the section-title links on the Nullify welcome panel opens a second Settings dialog stacked on top of the first one. The new dialog opens with the selected section already focused, but the original dialog remains visible underneath, requiring the user to close both windows. [!SEARCH] The Nullify welcome panel uses ShowSettingsUtil.showSettingsDialog(project, ConfigurableClass) to navigate from one Configurable to another. In non-modal mode (the default since IntelliJ 2024.1), this call reuses the existing settings window by routing through SettingsVirtualFileHolder and reselecting in-place. In legacy modal mode, the same call always opens a new modal dialog, because the platform's modal code path unconditionally creates a fresh dialog and does not consult any \"is a settings dialog already open\" state. (To be filled when handled.)"},{"id":"NL-F1","kind":"feature","title":"Navigation Support","status":"Completed(`0.1.0`)","url":"features/NL-F1.html","statusLabel":"Completed: on version 0.1.0","content":"Folding is quite stable now, but with types folded, \"Go to Definition\" no longer works. Doing Ctrl + left-click just unfolds the placeholder text, while F12 just does nothing. Ctrl+clicking a folded type now navigates to the type or annotation declaration. Simple types map the click position to the type name or the ?/! marker; complex generic types show all candidate targets for IntelliJ's navigation popup. Known limitations are tracked in NL-I16."},{"id":"NL-F2","kind":"feature","title":"Better Local Variable Support: Dataflow Integration","status":"Ditched(not worthy to be implemented)","url":"features/NL-F2.html","statusLabel":"Ditched: because \"not worthy to be implemented\"","content":"IntelliJ does a lot of jobs on local variable's dataflow analyzing. It is smart enough to tell you whether this invoke may cause NPE, or guarantees the safety of this external variable, however, it is not care enough for reviewing, since IntelliJ knows dataflow, not user. So, it is a good idea to infer the nullability from dataflow, and fold to make dataflow explicit."},{"id":"NL-F3","kind":"feature","title":"New Lint: Duplicated Nullability Annotation Usage","status":"Completed(`0.6.0`)","url":"features/NL-F3.html","statusLabel":"Completed: on version 0.6.0","content":"For projects like CRUD, related framework often depends on Jakarta, Javax, Lombok, etc. All of them has their own nullability annotation. Jakarta (jakarta.annotation.Nonnull), Lombok (lombok.NonNull) and Javax (javax.annotation.Nonnull)'s annotation name is very similar to each other, making it easy to import multi NotNulls when developer didn't keep eyes on code. A new \"Inconsistent Nullability Annotation\" inspection detects duplicated and mixed-namespace nullability annotations within a file, with quick fixes to remove a duplicate annotation or replace it with the file's canonical one."},{"id":"NL-F4","kind":"feature","title":"More Folding Support on Generics","status":"Completed","url":"features/NL-F4.html","statusLabel":"Completed: on version ","content":"Since ? extends → out and ? super → in is supported, why not adding these in independent generic declaration, instead of just showing this in nullability annotated targets? Confirmed that method-call type arguments are already handled and that Nullify does not create fold regions for them; a defensive guard prevents future regressions."},{"id":"NL-F5","kind":"feature","title":"UI Config","status":"Completed(`0.2.0`)","url":"features/NL-F5.html","statusLabel":"Completed: on version 0.2.0","content":"Config UI is not designed yet. So we need to do it ASAP. A settings page under Settings → Editor → Nullify lets users toggle nullity folding and wildcard folding independently, register custom @Nullable/@NotNull annotation types, and apply configuration changes immediately without restarting the IDE."},{"id":"NL-F6","kind":"feature","title":"Real Kotlin Styled Folded Type","status":"Completed(`0.4.0`)","url":"features/NL-F6.html","statusLabel":"Completed: on version 0.4.0","content":"Nullify's default folding style is actually different from Kotlin. A \"Kotlin-style nullity markers\" option places the ?/! markers after the generic type arguments (e.g. List<String!>?, matching Kotlin) instead of before them (e.g. List?<String!>, the default Nullify style)."},{"id":"NL-F7","kind":"feature","title":"\"Template Mode\"","status":"Accepted(1)","url":"features/NL-F7.html","statusLabel":"Accepted: priority 1","content":"Nullify does a lot of things on ASTNode Parsing. Of course, this is a good QoL, but reversing this process will be also useful and attractive. What is \"Template Mode\"?   Most IntelliJ Users have been used \"Living Templates\", sout, fori, C... \"Template Mode\" is similar to this, it transforms DSL that Nullify uses in folding placeholder texts to corresponding type, and supports other nullability-related template snippets. Why not Living Templates?Living Templates supports no target/one target to manipulate.Any symbols are all illegal in Living Templates.Template Mode is aimed to support completion hint, its final UX could be as good as Living Templates.How to use?   Using it could be very easy: templates are all focused on !, ? and . (may also invoke in, out, Array and Vararg). Note that ? and ! are not completely illegal in Java — ? is the ternary operator's separator, ! is the unary negation / != operator, and ? may also appear in wildcard positions (List<? extends Foo>) when wildcard folding is disabled — so the implementation distinguishes template suffix positions from legal Java positions before offering any expansion.    Examples: Foo? → Enter/Tab → Select Nullables to import → @Nullable FooMap!<out CharSequence!, Array?<Object!>> → Enter/Tab → Select Nullables and NotNulls to import → @NotNull Map<? extends @NotNull CharSequence, @NotNull Object @Nullable []>final var foo = bar!! → Enter/Tab → final var foo = Objects.requireNonNull(bar, \"Some Message That is Customizable\")foo.bar()?.baz() → Enter/Tab → if chains(when target type is not configured); fluent APIs(when type is Optional, Stream or configured)Lint Designs   ? and ! are illegal in the template positions Nullify targets (suffix after a type name, !!, ?.) — the Java parser reports those as error elements while legal uses (a ? b : c, x != y, !flag, List<? extends Foo>) parse cleanly. This means we can intercept lint on detecting the template-position usages, then check grammar legality.    Template Mode should support 2 entrances: Literally \"mode\": Turn on/off by hotkey (e.g. alt + *)Automatic (as above)   1 should be default, since 2 needs long-term feedback, enhances and bug-fixing."},{"id":"NL-F8","kind":"feature","title":"Class-Level & Package-Level Nullability Default Annotation Support","status":"Completed(`0.3.0`)","url":"features/NL-F8.html","statusLabel":"Completed: on version 0.3.0","content":"Annotations like org.jetbrains.annotations.NotNullByDefault (targets TYPE and PACKAGE) establish a default nullability for all elements within that scope. Currently, Nullify only supports: Direct annotations — type-use and declaration-site.Package-level parameter-only defaults — @ParametersAreNonnullByDefault / @ParametersAreNullableByDefault (javax/Jakarta), resolved from package-info.java.This feature adds full support for: Class-level defaults — e.g. @NotNullByDefault on a class declaration makes all fields, parameters, and return types within that class default to @NotNull.Package-level all-elements defaults — e.g. @NotNullByDefault on package-info.java should affect fields and return types too, not just parameters.Custom scope-default registration in settings — Users should be able to register arbitrary FQCNs as scope-level default annotations via the config UI, just as they can for direct nullability annotations today. Class-level and package-level nullability defaults are fully supported, and custom scope-default annotations can be registered in the settings UI. A related gap — scope defaults not propagating into nested type positions — is tracked in NL-I20."},{"id":"NL-F9","kind":"feature","title":"Smart Annotation FQCN Selection","status":"Completed(`0.9.0`)","url":"features/NL-F9.html","statusLabel":"Completed: on version 0.9.0","content":"Every annotation FQCN input in the settings currently uses plain text entry with no completion hints, only rejecting empty input on validation. Users should be able to: Get completion suggestions as they type, sourced from the project's Java PSI indexSee only annotation classes valid at the current call site (filtered by @Target)Have the picker gracefully degrade when no project is open (fall back to manual text entry with validation only) All annotation FQCN inputs now offer live completion popups, filtered by the call-site target. Built-in annotations are hidden and rejected in the registry tables, and the fields gracefully fall back to plain text entry when no project is open."},{"id":"NL-F10","kind":"feature","title":"Project-Level Default Nullability Annotation Configuration + Smart Quick Fix","status":"Completed(`0.8.0`)","url":"features/NL-F10.html","statusLabel":"Completed: on version 0.8.0","content":"When inconsistent nullability annotation usage from different namespaces appears on the same element (e.g., both @javax.annotation.Nonnull and @lombok.NonNull), users need a one-click solution that not only removes duplicates but also sets a project-level default annotation library, so future imports consistently use the same FQCN. Currently, the only available quick fixes are \"Remove annotation\" (per-annotation deletion) and \"Replace with canonical\" (per-file majority vote). These are functional but do not address the root cause — the user has no configured preference for which nullability annotation library their project uses. Nullify now supports a project-wide default @Nullable/@NotNull annotation FQCN, shared with the whole team through VCS. The inconsistent-nullability inspection offers two smart quick fixes: \"Set as project default\" (adopts the file's majority annotation as the project's default) and \"Replace with project default\" (replaces non-conforming annotations with the project's preferred annotation)."},{"id":"NL-F11","kind":"feature","title":"Mixed Nullability Namespace Check (File-Level Consistency)","status":"Ditched(merged into NL-F3)","url":"features/NL-F11.html","statusLabel":"Ditched: because \"merged into NL-F3\"","content":"The per-element duplicate check only catches the rare case where multiple @NotNull/@Nullable annotations are placed on the same element. Far more common in practice is file-level namespace mixing — different elements in the same file use nullability annotations from different libraries: This feature was merged into the inconsistent-nullability inspection (NL-F3): the file-level namespace check now reports annotations whose namespace differs from the file's canonical one, with a replace-with-canonical quick fix."},{"id":"NL-F12","kind":"feature","title":"PSI-Anchored Fold Navigation — Replace Placeholder Text Re-Parsing with Fold-Time Segment Mapping","status":"Completed(`1.0.0`)","url":"features/NL-F12.html","statusLabel":"Completed: on version 1.0.0","content":"Fold navigation today works by reparsing the folded placeholder text and guessing which declaration a clicked part refers to. This is fragile: the placeholder is only a compact rendering, so the parser must re-derive the original meaning from a lossy string. Each new fold form (arrays, varargs, wildcards, var, generics, annotation arguments) has repeatedly required a matching navigation patch, and annotation arguments are not understood at all — clicking name/value inside a preserved @MyAnno(name = \"foo\", value = \"bar\") jumps to the field's type instead of the annotation's element methods (see NL-I35). A more compatible architecture is to never reparse the placeholder. Since the folded text is produced from the original PSI at fold time, the fold itself should record a mapping from each placeholder segment back to the originating PSI element. Navigation then becomes a trivial lookup plus delegation to that original element's native navigation — the IDE already knows how to navigate annotation arguments to element methods, type references to declarations, and imports to their targets. Navigation configuration (custom annotation registries, import disambiguation) is inherited from the platform for free. Navigation on folded types no longer reparses the displayed text. Each fold records where its visible parts came from in the original code, and clicking any part — including annotation arguments like name = \"foo\" — jumps to the exact declaration the IDE would have shown before folding. This also fixes the annotation-argument navigation regression in NL-I35."},{"id":"NL-F13","kind":"feature","title":"Generic Annotation Value Navigation — Folded Literals Delegate to the Platform","status":"Completed(`1.0.0`)","url":"features/NL-F13.html","statusLabel":"Completed: on version 1.0.0","content":"When a non-nullity annotation with a value member is preserved inside a folded placeholder (e.g. @Value(\"${app.name}\") Foo!), the value literal currently has no navigation target — even though the same literal clicked outside a fold would navigate somewhere meaningful (Spring's @Value jumps to the config key, @Qualifier to the bean, @Profile to the profile, …). Nullify must not hard-code any of these domains: it hands the literal back to the IDE's own navigation machinery, and installed framework plugins resolve it exactly as if the user had clicked the literal in unfolded code. Clicking an annotation value literal inside a folded placeholder — e.g. Spring's @Value(\"${app.name}\") — now navigates exactly as it would in unfolded code: the IDE's own machinery (installed framework plugins, native references) resolves it to the config key, bean, profile, or whatever that framework defines. Literals with nothing to resolve keep the current no-target behavior, and the fold stays collapsed."},{"id":"NL-F14","kind":"feature","title":"Auto-Collapse Nullify Folds After Project Analysis Completes","status":"Completed(`1.0.0`)","url":"features/NL-F14.html","statusLabel":"Completed: on version 1.0.0","content":"When a project finishes its analysis (indexing), the fold regions Nullify created in the editor tab the user is currently using are collapsed automatically, so the compact String?/Foo! syntax is visible without the user having to fold them manually. Only the active editor tab is affected — background tabs, and non-Nullify folds such as method bodies and imports, are left untouched. The behavior is user-configurable. After the project finishes its analysis, the Nullify fold regions in the editor tab you are currently using are collapsed automatically, so the compact folded syntax is shown immediately. Other tabs and non-Nullify folds are not affected. This can be turned off under Settings → Editor → Nullify → Folding Behavior."},{"id":"NL-F15","kind":"feature","title":"Runnable Folding Demo (`NullifyDemo`)","status":"Completed(`1.0.0`)","url":"features/NL-F15.html","statusLabel":"Completed: on version 1.0.0","content":"A small set of runnable Java demo files that showcase every folding capability the plugin provides. Opening them in the IDE with Nullify installed shows the compact String?/Map!<String!>-style syntax immediately, and each file has a main method so the underlying code also runs. The core NullifyDemo class demonstrates nullity annotations (?/!), preserved non-nullity annotations, qualified types and annotated var locals, while the companion files cover var inference, arrays/varargs, and wildcards/generics/intersection casts. Opening NullifyDemo (or any demo file in kurvcygnus.nullify.demo) with Nullify installed folds every annotated element into its compact form, and running the main method prints the values those types actually hold, proving the demo is real, compilable Java."},{"id":"NL-F16","kind":"feature","title":"Nullability Reason Inline Hints — `value` Reason Displayed Above Collapsed Folds","status":"Completed(`1.0.0`)","url":"features/NL-F16.html","statusLabel":"Completed: on version 1.0.0","content":"When Nullify collapses @NotNull/@Nullable into compact !/? markers, the annotation's optional, documentation-oriented value member — e.g. @Nullable(\"returns null when no entry matches\") — is swallowed entirely. That reason text is exactly what a reader of collapsed code is missing. This feature restores it as a hint rendered in the line gap directly above the collapsed fold — the same presentation style Better Highlights uses for method complexity — reading This is nullable because \"returns null when no entry matches\". The hint targets the top-level type's nullability: for List<Map<String, Pair<Integer, Char>>> it is the List's ?/! mark that is described. It appears only while the fold is collapsed (expanding the fold reveals the source and removes the hint), and only when the annotation actually supplies a reason — no value, no hint. A Settings → Editor → Nullify toggle switches it off entirely. Nullify now shows the reason a value is nullable or not-null right above the collapsed fold — This is nullable because \"returns null when no entry matches\". — exactly where a reader of collapsed code is missing it. The hint describes the top-level type's nullability (the List in List<Map<String, Pair<Integer, Char>>>), appears only while the fold is collapsed, and is suppressed when the annotation carries no reason. It can be turned off under Settings → Editor → Nullify."},{"id":"NL-F17","kind":"feature","title":"Long Nullability Reasons — Multi-Line Reason Hints with Expand/Collapse","status":"Ditched(merged into NL-F20)","url":"features/NL-F17.html","statusLabel":"Ditched: because \"merged into NL-F20\"","content":"When a nullability annotation carries a long reason, the current single-line hint truncates it and clips the tail — the reader loses the most important part. This feature lets the hint take multiple lines and gives the user control over how much of the reason is shown. By default(configurable under Settings → Editor → Nullify), long reasons are collapsed: the hint shows a truncated sentence such as \"This is nullable because \"returns null when no entry matches …\"\" — with the elided tail marked by …. Expanding the hint reveals the full reason on the next line, so the collapsed one-liner stays compact while the complete text is one click (or shortcut) away. Long nullability reasons no longer get clipped off-screen. The hint shows a compact truncated sentence — \"This is nullable because \"returns null when no entry matches …\"\" — by default, and can be expanded to read the full reason on the following line, by clicking the hint, clicking a gutter icon, or via a keyboard shortcut. A Settings → Editor → Nullify toggle chooses whether long hints start collapsed."},{"id":"NL-F18","kind":"feature","title":"Reason Hint Colors Through the Editor Color Scheme — Replace the Single-Hex Setting","status":"Ditched(merged into NL-F20)","url":"features/NL-F18.html","statusLabel":"Ditched: because \"merged into NL-F20\"","content":"The reason hint currently supports only a single custom foreground color chosen under Settings → Editor → Nullify (one RRGGBB value, off by default). That does not play well with IntelliJ's theming: switching between light/dark schemes keeps one hard-coded color, and there is no way to theme background/effects or preview the hint in the IDE's color scheme editor. This feature makes the reason hint a first-class citizen of the Editor Color Scheme: a new Nullify color page under Settings → Editor → Color Scheme with a theme-able \"Reason hint\" attribute (foreground, background, effects, bold/italic), sharing the look of the rest of the editor's hints and following scheme switches automatically. The nullability reason hint is now a fully theme-able editor color: it appears as a \"Reason hint\" attribute under Settings → Editor → Color Scheme → Nullify (foreground, background, effects), follows light/dark scheme switches automatically, and the old single-hex color setting is gone."},{"id":"NL-F19","kind":"feature","title":"Configurable Prefix for Nullability Reason Inline Hints","status":"Ditched(merged into NL-F20)","url":"features/NL-F19.html","statusLabel":"Ditched: because \"merged into NL-F20\"","content":"The nullability reason hint (NL-F16) currently renders as a bare sentence — This is nullable because \"returns null when no entry matches\". — with nothing to tie it to Nullify at a glance. This feature gives the final rendered text a configurable prefix: none (default), *, •, §, a user-typed custom symbol, or the Nullify Gutter icons (Nullable.svg / NotNull.svg), where the icon shown is chosen by the folded type's top-level nullability mark. Whenever a prefix is active, exactly one space separates it from the hint text so it never reads cramped. The nullability reason hint can now carry a leading prefix chosen under Settings → Editor → Nullify → Folding Behavior: none (default), *, •, §, your own symbol, or Nullify's Gutter icon — where the icon reflects the fold's nullability (Nullable.svg for nullable, NotNull.svg for not-null). As long as a prefix is set, exactly one space separates it from the hint text, and changes apply to every open editor immediately."},{"id":"NL-F20","kind":"feature","title":"Reason Hint Enhancements — Multi-Line Reasons, Editor Color Scheme, Configurable Prefix, and Font Size","status":"Completed(`1.0.0`)","url":"features/NL-F20.html","statusLabel":"Completed: on version 1.0.0","content":"The nullability reason hint (NL-F16) is a single-line sentence rendered in the editor's normal font and color, with no way to read a long reason in full, tie the hint to Nullify at a glance, or make it visually distinct from code. This feature package turns the hint into a fully customizable, first-class editor citizen: long reasons collapse into a truncated one-liner and expand to the complete multi-line text (by clicking the hint, using the gutter's standard fold arrow, or a keyboard shortcut); the hint's color becomes a proper Editor Color Scheme attribute (Settings → Editor → Color Scheme → Nullify) instead of a single hard-coded hex; an optional leading prefix (*, •, §, a custom symbol, or Nullify's Nullable.svg/NotNull.svg gutter icon) marks the hint at a glance; and the hint font can be sized relative to the editor font (default: one pixel smaller) so it reads as a layered annotation rather than ordinary code. This feature consolidates NL-F17 (multi-line + expand/collapse), NL-F18 (color scheme integration), and NL-F19 (configurable prefix) into one package, and adds the configurable font size. The nullability reason hint is now a theme-able, configurable editor citizen: long reasons collapse into a compact truncated sentence (This is nullable because \"returns null when no entry matches …\") and expand to the full multi-line text on click, via the fold arrow, or with a keyboard shortcut; its color lives under Settings → Editor → Color Scheme → Nullify (foreground/background/effects, following light/dark scheme switches); it can carry a leading prefix (*, •, §, a custom symbol, or the Nullify gutter icon matching the fold's nullability); and its font size is adjustable relative to the editor font (default one pixel smaller). The old single-hex color setting is gone."},{"id":"NL-F21","kind":"feature","title":"CommentMaybeReasonInspection — Migrate Adjacent Comments into Nullability Annotation Reasons","status":"Completed(`1.0.0`)","url":"features/NL-F21.html","statusLabel":"Completed: on version 1.0.0","content":"[!LIGHTBULB] Developers often explain why a value is nullable or non-null in a free-floating comment next to the annotation: // Returns null when no entry matches\n@Nullable\nString find(String key); Such comments are easy to overlook — they sit outside the type system, are lost once the declaration is folded, and duplicate what the annotation itself was designed to carry. Annotations declaring a String value() member (e.g. JetBrains @NotNull/@Nullable) already provide a first-class home for exactly this sentence: @Nullable(\"Returns null when no entry matches\"). Once migrated, the reason stays attached to the type, survives folding, and is rendered by Nullify's reason hints (NL-F16) above collapsed folds. CommentMaybeReasonInspection detects a nullability annotation that: has a comment directly above it (same physical adjacency, no blank line or other element in between) or trailing on its right on the same line;belongs to an annotation type that supports a reason field (declares a String value() member);currently carries no valid reason value.and offers a quick fix that migrates the comment's content into the annotation's value and removes the comment. The inspection is quick-fix only by default — it never highlights anything in the editor; the migration simply appears on Alt+Enter. When a nullability annotation that supports a reason field (e.g. JetBrains @NotNull/@Nullable) sits directly next to a comment — on the line above it or trailing on its right — and carries no reason of its own, Nullify offers a quick fix on Alt+Enter that moves the comment's text into the annotation as its value reason and removes the comment: // Returns null when no entry matches\n@Nullable\nString find(String key); becomes @Nullable(\"Returns null when no entry matches\")\nString find(String key); The inspection never highlights anything by itself — it is purely a quick-fix provider. Javadoc comments and annotations without a reason field are left untouched."},{"id":"NL-F22","kind":"feature","title":"AppendNullabilityDocIntention — Nullability Javadoc Sentences for Undocumented Elements","status":"Completed(`1.0.0`)","url":"features/NL-F22.html","statusLabel":"Completed: on version 1.0.0","content":"[!LIGHTBULB] A nullability annotation (@Nullable, @NotNull, …) tells the compiler and the linter how a value behaves, but the people reading the code often learn it from the Javadoc instead: @param key a String which is nullable because it is absent for anonymous users. Writing that sentence by hand is tedious — the annotation already carries the nullability mark, so the sentence is almost fully derivable. Still, it is exactly the kind of documentation that readers expect and that code generators and IDEs surface. AppendNullabilityDocIntention closes the gap on Alt+Enter. It fires when both conditions hold: the target element carries a registered nullability annotation (built-in or user-registered — custom annotation libraries participate);the element's Javadoc does not document it yet — a method parameter without its @param tag, a return type without @return, a thrown type without @throws, a type parameter without its @param <T> tag, or a field/class without any Javadoc comment at all.The generated sentence follows a kind-adaptive template — it is never a fixed @param … block, because the intention serves every Javadoc-able element: Method parameter → @param ${var_name}Method type parameter → @param <${type_param_name}>Method return type → @returnThrown exception type → @throws ${exception_name}Field / class (prose, no tag) → ${element_name}The shared body is: ${head} ${article} ${type_of_target} which is ${nullability_of_target}${select_start} because ${carpet_position}${select_end}. ${article} is resolved from the type name's initial sound (a vs an — an Integer, a String) — never a literal a(an).${select_start} and ${select_end} are auxiliary markers describing the selection bounds, not inserted text. After generation, the region between them — the reason clause  because  — is selected, while the sentence's closing period stays outside it.${carpet_position} marks where the caret lands, not inserted text: the caret sits right after because , at the selection's end.The selection is the point: a user who wants a reason simply types — the typed text replaces the selected clause, and the preserved period closes the sentence. A user who does not wants to be out in one keystroke: pressing Backspace deletes the whole  because  clause and leaves a complete sentence, e.g. @param key a String which is nullable.. The sentence is always English by default; other languages require an explicit opt-in in a project-level setting (Settings → Editor → Nullify), offering Always English (default) | Follow IDE language | Deutsch | Français | 日本語 | 简体中文. Javadoc targets a global developer audience, so following the IDE language by default would add noise rather than value. When a nullability-annotated element's Javadoc does not document it yet, Alt+Enter offers Append nullability Javadoc: it appends (or creates) the Javadoc sentence @param key a String which is nullable because <reason>. following the kind-adaptive template — @param/@return/@throws for tag-based targets, a prose sentence for fields and classes, with the English article (a/an) chosen from the type's sound. The reason clause  because  is inserted selected — with the closing period left in place — and the caret right after because : type a reason to replace it in one stroke, or press Backspace to drop the clause entirely and keep a complete sentence (@param key a String which is nullable.). The sentence is English by default; under Settings → Editor → Nullify a project-level option switches it to Follow IDE language or one of the fixed language modes (Deutsch, Français, 日本語, 简体中文)."}];
window.NULLIFY_STATUS_ICONS = {"Unknown":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"/><path d=\"M12 17h.01\"/></svg>","Open":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/></svg>","Ditched":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M4.929 4.929 19.07 19.071\"/></svg>","Researching":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><path d=\"m21 21-4.34-4.34\"/><circle cx=\"11\" cy=\"11\" r=\"8\"/></svg>","Handling":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.106-3.105c.32-.322.863-.22.983.218a6 6 0 0 1-8.259 7.057l-7.91 7.91a1 1 0 0 1-2.999-3l7.91-7.91a6 6 0 0 1 7.057-8.259c.438.12.54.662.219.984z\"/></svg>","Pending":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></svg>","Resolved":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m9 12 2 2 4-4\"/></svg>","Considering":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><path d=\"M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5\"/><path d=\"M9 18h6\"/><path d=\"M10 22h4\"/></svg>","Implementing":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><path d=\"m15 12-9.373 9.373a1 1 0 0 1-3.001-3L12 9\"/><path d=\"m18 15 4-4\"/><path d=\"m21.5 11.5-1.914-1.914A2 2 0 0 1 19 8.172v-.344a2 2 0 0 0-.586-1.414l-1.657-1.657A6 6 0 0 0 12.516 3H9l1.243 1.243A6 6 0 0 1 12 8.485V10l2 2h1.172a2 2 0 0 1 1.414.586L18.5 14.5\"/></svg>","Accepted":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><path d=\"M3.85 8.62a4 4 0 0 1 4.78-4.77 4 4 0 0 1 6.74 0 4 4 0 0 1 4.78 4.78 4 4 0 0 1 0 6.74 4 4 0 0 1-4.77 4.78 4 4 0 0 1-6.75 0 4 4 0 0 1-4.78-4.77 4 4 0 0 1 0-6.76Z\"/><path d=\"m9 12 2 2 4-4\"/></svg>","Completed":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"status-icon\"><path d=\"M18 6 7 17l-5-5\"/><path d=\"m22 10-7.5 7.5L13 16\"/></svg>"};
